 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Flood-fill background from the edge using 4-connectivity. Remaining
    # zero cells are the interior of closed contours.
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0, h - 1) or c in (0, w - 1)) and grid[r][c] == 0:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    # Find 8-connected outline components. Closed components receive an
    # exterior halo (2) and an interior-facing halo (3).
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    dirs8 = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen[r][c]:
                continue
            comp = []
            seen[r][c] = True
            q = deque([(r, c)])
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for dr, dc in dirs8:
                    nx, ny = x + dr, y + dc
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and not seen[nx][ny]:
                        seen[nx][ny] = True
                        q.append((nx, ny))
            inner = set()
            outer = set()
            for x, y in comp:
                for dr, dc in dirs8:
                    nx, ny = x + dr, y + dc
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0:
                        if outside[nx][ny]:
                            outer.add((nx, ny))
                        else:
                            inner.add((nx, ny))
            if inner:
                for x, y in inner:
                    out[x][y] = 3
                for x, y in outer:
                    out[x][y] = 2
    return out
